CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;
CREATE TABLE "Currencies" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ShortName" text NOT NULL,
    "FullName" text NOT NULL,
    "ToRubleRate" numeric NOT NULL,
    CONSTRAINT "PK_Currencies" PRIMARY KEY ("Id")
);

CREATE TABLE "Goods" (
    "Code" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" text NOT NULL,
    "PriceRub" numeric NOT NULL,
    "Count" integer NOT NULL,
    CONSTRAINT "PK_Goods" PRIMARY KEY ("Code")
);

INSERT INTO "Currencies" ("Id", "FullName", "ShortName", "ToRubleRate")
VALUES (1, 'Рубли', 'RUB', 1.0);
