SELECT setval(
    pg_get_serial_sequence('"Currencies"', 'Id'),
    GREATEST(
        (SELECT MAX("Id") FROM "Currencies") + 1,
        nextval(pg_get_serial_sequence('"Currencies"', 'Id'))),
    false);
SELECT setval(
    pg_get_serial_sequence('"Goods"', 'Code'),
    GREATEST(
        (SELECT MAX("Code") FROM "Goods") + 1,
        nextval(pg_get_serial_sequence('"Goods"', 'Code'))),
    false);

INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
VALUES ('20260614075709_InitialCreate', '10.0.4');

COMMIT;

